import { total } from './cart.js';

// Invoices for wholesale orders (#7). Wholesale customers order from a printed price
// list: list price below 10 lines, 5% off from 10 lines, half a yen rounded up.
// The cart's own bulk discount now starts at 2 lines, so the price list's threshold
// is passed explicitly; the amount due is otherwise the cart total as it is.
const PRICE_LIST_BULK_MIN_LINES = 10;

export function invoice(customer, items) {
  return { customer, due: total(items, 0, PRICE_LIST_BULK_MIN_LINES) };
}
