test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }]), 200); // 1 line: below the bulk threshold
});

// #12: a 0.1 customer buying a 1,000 yen cart (below the bulk threshold) pays 900
test('customer discount is applied once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

